function classNames(...classes: Array<string | false | undefined>) { return classes.filter(Boolean).join(' '); }

function ImageTile({ src, label, className = '' }: { src?: string; label: string; className?: string }) {
  const [failed, setFailed] = useState(false);
  return (
    <div className={classNames('relative overflow-hidden bg-[#dfd1bd]', className)}>
      {src && !failed ? <img src={src} alt={label} onError={() => setFailed(true)} className="h-full w-full object-cover transition-transform duration-500 hover:scale-[1.04]" /> : (
        <div className="relative h-full w-full overflow-hidden bg-[radial-gradient(circle_at_30%_15%,#f5e8d1_0,#bea98e_38%,#7a5a55_100%)]">
          <div className="absolute left-[22%] top-[8%] h-[112%] w-[56%] rotate-[8deg] rounded-[45%_45%_18%_18%] bg-[#f4e8d4] shadow-[inset_-18px_-10px_35px_rgba(65,35,36,.16)]" />
          <div className="absolute bottom-[7%] left-[8%] h-[36%] w-[84%] rounded-[50%] bg-[#743143]/70 blur-2xl" />
          <span className="absolute bottom-3 left-3 max-w-[75%] text-[10px] font-semibold uppercase tracking-[.16em] text-[#4f3130]">{label}</span>
        </div>
      )}
    </div>
  );
}

